from pathlib import Path
root=Path('/home/user/Desktop/inventory-system')
guide=root/'docs/user-guide/index.html'
s=guide.read_text();mark='<section id="laptop" data-admin="true"><h2>Admin: edit from a laptop</h2>'
assert mark in s
s=s.replace(mark,mark+'<aside><b>Direct Homebox access is now enabled.</b> For the standard inventory interface, join the same network and open <b>http://192.168.1.61:17745</b>, or <b>http://10.77.0.1:17745</b> over the direct laptop cable. Sign in with your Homebox account; no tunnel is needed. Use the Pi desktop <b>Connection Info</b> to find its current address after changing Wi-Fi. The Workshop Editor instructions below still apply to the companion and map editor.</aside>')
guide.write_text(s)
(Path.home()/'Desktop/Equipment User Guide.html').write_text(s.replace('src="images/','src="inventory-system/docs/user-guide/images/'))
f=root/'docs/LAPTOP_ACCESS.md';s=f.read_text();s=s.replace('The companion and Homebox remain bound to loopback on the Pi.','The companion remains bound to loopback. Homebox now accepts direct authenticated network access on port 17745; open http://PI_ADDRESS:17745 from another device on the same network. Use Connection Info on the Pi desktop for its current address.')
f.write_text(s)
(root/'docs/homebox-access.html').write_text('''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Homebox network access</title><style>body{font:20px/1.6 Arial,sans-serif;max-width:850px;margin:40px auto;padding:24px;color:#17384a}a{color:#245c89}</style><h1>Homebox network access</h1><p>On a laptop, phone, or tablet connected to the same network, open <a href="http://192.168.1.61:17745">http://192.168.1.61:17745</a> and sign in with your Homebox email and password. No SSH tunnel or launcher is needed.</p><p>For the direct laptop cable, open <a href="http://10.77.0.1:17745">http://10.77.0.1:17745</a>. On the Pi itself, use http://127.0.0.1:17745.</p><p>After changing Wi-Fi, open <b>Connection Info</b> on the Pi desktop to find its current address. Guest Wi-Fi can block access between devices. Internet is not required for Homebox.</p><p>The companion and workshop editor still use the existing Workshop Editor tunnel. Codex phone pairing does not expose these browser services. Use Equipment Terminal for checkout, returns, badges, and return-note logs.</p><p>Homebox listens on the Pi network interfaces and retains its normal login. Access from outside this network requires a separately configured remote access method.</p><a href="user-guide/index.html">Full user and administrator guide</a></html>''')
print('Updated current guide and laptop access instructions for direct Homebox access.')
